data.body:
{
  "markdown": "**{{alertType}}**
Alert ID: {{alertId}}
Alert level: {{alertLevel}}
Occurred at: {{occurredAt}}
Organization name: [{{organizationName}}]({{organizationUrl}})
Organization ID: {{organizationId}}
Network name: [{{networkName}}]({{networkUrl}})
Network ID: {{networkId}}
Network Tags: {{networkTags | join: ', '}}
Device name: {{deviceName}}
Device serial: [{{deviceSerial}}]({{deviceUrl}})
Device MAC: {{deviceMac}}
Device tags: {{deviceTags | join: ', '}}
Device model: {{deviceModel}}
**Alert Data** {{ alertData | markdown_with_additional_formatting_for_webex }}
"
}

{
  "text": "{{alertType}}",
  "blocks": [
    {
      "type": "header",
      "text": {
        "type": "plain_text",
        "text": "{{alertType}}"
      }
    },
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "Alert ID: {{alertId}}\nAlert level: {{alertLevel}}\nOccurred at: {{occurredAt}}\n"
      }
    },
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "Organization name: *<{{organizationUrl}}|{{organizationName}}>*\nOrganization ID: {{organizationId}}\n"
      }
    },
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "Network name: *<{{networkUrl}}|{{networkName}}>*\nNetwork ID: {{networkId}}\nNetwork Tags: {{networkTags | join: ', '}}\n"
      }
    },
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "Device name: {{deviceName}}\nDevice serial: <{{deviceUrl}}|{{deviceSerial}}>\nDevice MAC: {{deviceMac}}\nDevice tags: {{deviceTags | join: ', '}}\nDevice model: {{deviceModel}}\n"
      }
    },
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "Alert data: {{ alertData | markdown_with_additional_formatting_for_slack }}\n"
      }
    }
  ]
}

{
  "type": "message",
  "attachments": [
    {
      "contentType": "application/vnd.microsoft.card.adaptive",
      "content": {
        "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
        "type": "AdaptiveCard",
        "version": "1.4",
        "body": [
          {
            "type": "TextBlock",
            "text": "{{organizationName}}",
            "weight": "Bolder",
            "size": "Large",
            "wrap": true
          },
          {
            "type": "TextBlock",
            "text": "{{networkName}}",
            "isSubtle": true,
            "spacing": "None",
            "wrap": true
          },
          {
            "type": "Container",
            "{% if alertData.imageUrl %}items{% endif %}": [
              {
                "type": "Image",
                "url": "{{alertData.imageUrl}}",
                "size": "Large"
              }
            ]
          },
          {
            "type": "FactSet",
            "facts": [
              {
                "title": "When",
                "value": "{{occurredAt}}"
              },
              {
                "title": "Device",
                "value": "{{deviceName}}"
              },
              {
                "title": "Alert",
                "value": "{{alertType}} - {{alertLevel}}"
              },
              {
                "title": "Alert Data",
                "value": "{{alertData | markdown_with_additional_formatting_for_teams}}"
              }
            ]
          }
        ],
        "actions": [
          {
            "type": "Action.OpenUrl",
            "title": "Organization",
            "url": "{{organizationUrl}}"
          },
          {
            "type": "Action.OpenUrl",
            "title": "Network",
            "url": "{{networkUrl}}"
          },
          {
            "type": "Action.OpenUrl",
            "title": "Device",
            "url": "{{deviceUrl}}"
          }
        ]
      }
    }
  ]
}

{
  "payload": {
    "summary": "{{alertType}}",
    "timestamp": "{{occurredAt}}",
    {% if networkId %}
    "source": "{{networkId}}",
    {% else %}
    "source": "{{organizationId}}",
    {% endif %}
    "severity": "{% if alertLevel == 'informational' %}info{% else %}warning{% endif %}",
    "component": "{{deviceName}}",
    "group": "{{networkName}}",
    "class": "deploy",
    "custom_details": {{alertData | jsonify}}
  },
  "routing_key": "{{sharedSecret}}",
  "dedup_key": "{{alertId}}",
  "images": [
{% if alertData.imageUrl %}
    {
      "src": "{{alertData.imageUrl}}",
      "href": "{{alertData.imageUrl}}",
      "alt": "Image"
    }
{% endif %}
  ],
  "links": [
  {% if deviceUrl %}
    {
      "href": "{{deviceUrl}}",
      "text": "{{deviceName}}"
    },
  {% endif %}
  {% if networkUrl %}
    {
      "href": "{{networkUrl}}",
      "text": "{{networkName}}"
    },
  {% endif %}
    {
      "href": "{{organizationUrl}}",
      "text": "Organization"
    }
  ],
  "event_action": "trigger",
  "client": "Manage Meraki Device",
  "client_url": "{{deviceUrl}}"
}

